.admin-home {
  min-height: 100vh;
  padding: 30px;

  background: url("../../assets/chillilogo-bg.png") center/cover no-repeat !important;

  position: relative;
}
.admin-home > * {
  position: relative;
  z-index: 1;
}
/* 🔥 OVERLAY + BLUR */
.admin-home::before {
  content: "";
  position: absolute;
  inset: 0;

  background: rgba(10, 20, 60, 0.65);

  z-index: 0;
}
/* KEEP CONTENT ABOVE */
.admin-home > * {
  position: relative;
  z-index: 1;
}

/* GRID */
.admin-stats-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 20px;
  margin-bottom: 30px;
}

/* CARD */
/* ICON */
.admin-card-icon {
  font-size: 22px;
  color: #ffd000;
  margin-bottom: 10px;
}

/* TEXT */
.admin-stat-card h2 {
  color: #d1d5db;
  font-size: 16px;
}

.admin-stat-card h1 {
  color: white;
  font-size: 28px;
  margin: 10px 0;
}

.admin-stat-card p {
  color: #ffd000;
}

/* ANALYTICS */
.admin-analytics-grid {
  display: grid;
  grid-template-columns: 2fr 1fr;
  gap: 20px;
  margin-bottom: 30px;
}

/* LOWER */
.admin-lower-grid {
  display: grid;
  grid-template-columns: 2fr 1fr;
  gap: 20px;
}

/* BOX */
.admin-chart-box {
  background: rgba(25, 35, 70, 0.85);
  padding: 20px;
  border-radius: 18px;
}

/* HEADER */
.box-header {
  display: flex;
  justify-content: space-between;
  margin-bottom: 15px;
}

.box-header h2 {
  color: white;
}

.box-header button {
  background: #ffd000;
  border: none;
  padding: 5px 12px;
  border-radius: 8px;
  color: white;
   font-weight: 400;
  font-size: 20px;
}

/* CIRCLE */
.circle-wrapper {
  display: flex;
  justify-content: space-between;
}

.circle-card {
  text-align: center;
}

.circle-progress {
  width: 70px;
  height: 70px;
  border: 4px solid #ffd000;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  margin: auto;
  color: white;
}

/* STOCK */
.stock-item {
  display: flex;
  justify-content: space-between;
  margin-bottom: 10px;
}

.available { color: #22c55e; }
.low { color: #f97316; }
.out { color: #ef4444; }

