.fake-graph{
  width: 100%;

  height: 220px;

  background: #101935;

  border-radius: 16px;

  position: relative;

  overflow: hidden;

  padding: 20px;
}





/* LINE GRAPH */
.line{
  position: absolute;

  left: 0;
  top: 0;

  width: 100%;
  height: 100%;

  background: none;
}



.line::before{
  content: "";

  position: absolute;

  width: 100%;
  height: 100%;

  border-radius: 16px;

  background: linear-gradient(
    to bottom,
    rgba(255,208,0,0.18),
    transparent
  );

  clip-path: polygon(
    0% 78%,
    8% 68%,
    16% 72%,
    24% 55%,
    32% 58%,
    40% 40%,
    48% 52%,
    56% 32%,
    64% 42%,
    72% 24%,
    80% 35%,
    88% 20%,
    100% 28%,
    100% 100%,
    0% 100%
  );
}





.line::after{
  content: "";

  position: absolute;

  width: 100%;
  height: 100%;

  clip-path: polygon(
    0% 78%,
    8% 68%,
    16% 72%,
    24% 55%,
    32% 58%,
    40% 40%,
    48% 52%,
    56% 32%,
    64% 42%,
    72% 24%,
    80% 35%,
    88% 20%,
    100% 28%
  );

  border-top: 4px solid #ffd000;
}





/* REVENUE GRAPH */
