/* =========================================
FOOD ACTIONS
========================================= */

.food-actions {

  margin-top: 15px;

  display: flex;

  flex-direction: column;

  gap: 12px;
}



/* =========================================
AVAILABILITY
========================================= */

.availability-box {

  display: flex;

  justify-content: space-between;

  align-items: center;
}



.available-text {

  color: #22c55e;

