  if (!confirmDelete)
    return;







  try {

    await axios.delete(

      `https://cvru-cms.onrender.com/api/v1/foods/${foodId}`,

      {
        withCredentials: true
      }
    );







    // REMOVE FROM UI
    setFoods(

      foods.filter(

        (item) =>

          item._id !== foodId
      )
    );







    toast.success(
      "Food Deleted"
    );

  } catch (error) {

    console.log(error);

    toast.error(
      "Delete Failed"
    );
  }
};
  /* ---------------- UPDATE AVAILABILITY STATUS ---------------- */
  // eslint-disable-next-line no-unused-vars
  const updateFood = async (id) => {

  try {

    const response =
      await API.put(

        `/foods/availability//${id}`,

        {

          name,

          price,

          category
        }
      );



    alert(
      response.data.message
    );

  } catch (error) {

    console.log(error);

    alert(
      error.response?.data?.message
    );
  }
};

  /* ---------------- DELETE FOOD ---------------- */


  

  // const updateLunchStatus = (id, newStatus) => {
  //   setLunchMenu((prev) =>
  //     prev.map((item) => (item.id === id ? { ...item, status: newStatus } : item))
  //   );
  // };

  /* ---------------- FILTER LOGIC ---------------- */
  const filteredFoods = foods.filter((item) => {
    const matchCategory = activeCategory === "All" ? true : item.category === activeCategory;
    const matchSearch = item.name.toLowerCase().includes(searchTerm.toLowerCase());
    return matchCategory && matchSearch;
  });

  return (
    <div
      className="admin-menu-page"
      style={{
        //backgroundImage: `url(${bannerImg})`,
