            <div className="food-content">
              <h2>{item.name}</h2>
              <h3>₹ {item.price}</h3>
              <div className="food-status">
 <div className="food-actions">

  {/* AVAILABILITY */}

  <div className="availability-box">

    <span
      className={
        item.isAvailable

          ? "available-text"

