import "../css/AdminOrders.css";

import { useEffect, useState } from "react";

import axios from "axios";

import bgImage from "../../assets/chilli-bg.png";

import socket from "../../socket";

import {

  FaClipboardList,

  FaCheckCircle,

  FaUtensils,

  FaBoxOpen,

  FaClock,

  FaTimesCircle,

  // eslint-disable-next-line no-unused-vars
  FaShoppingBag

} from "react-icons/fa";

// eslint-disable-next-line no-unused-vars
import { toast } from "react-toastify";

function AdminOrders() {

  // =========================================
  // STATES
  // =========================================

  const [orders, setOrders] =
    useState([]);

  const [selectedOrder, setSelectedOrder] =
    useState(null);

  const [loading, setLoading] =
    useState(true);





  // =========================================
  // FETCH ORDERS
  // =========================================

  const fetchOrders =
    async () => {

      try {

        const response =
          await axios.get(

            "https://cvru-cms.onrender.com/api/v1/orders/admin/active-orders",

            {
              withCredentials: true
            }
          );





        console.log(
          "ADMIN ORDERS:",
          response.data
        );





        const allOrders =

          response.data.orders ||

          response.data.data ||

          [];





        setOrders(allOrders);





        if (
          allOrders.length > 0
        ) {

          setSelectedOrder(
            allOrders[0]
          );
        }





        setLoading(false);

      } catch (error) {

        console.log(
          "Error fetching admin orders:",
          error
        );

        setLoading(false);
      }
    };





  // =========================================
  // INITIAL FETCH
  // =========================================

  useEffect(() => {

    fetchOrders();

  }, []);





  // =========================================
  // SOCKET REALTIME
  // =========================================

  useEffect(() => {

    socket.on(

      "newOrderPlaced",

      (newOrder) => {

        console.log(
          "NEW ORDER:",
          newOrder
        );

        fetchOrders();
      }
    );





    socket.on(

      "orderStatusUpdated",

      (updatedOrder) => {

        console.log(
          "UPDATED ORDER:",
          updatedOrder
        );

        fetchOrders();
      }
    );





    return () => {

      socket.off(
        "newOrderPlaced"
      );

      socket.off(
        "orderStatusUpdated"
      );
    };

  }, []);





  // =========================================
  // UPDATE STATUS
  // =========================================

  const updateStatus =
    async (
      orderId,
      newStatus
    ) => {

      try {

        const response =
          await axios.put(

            `https://cvru-cms.onrender.com/api/v1/orders/admin/update-status/${orderId}`,

            {

              orderStatus:
                newStatus
            },

            {
              withCredentials: true
            }
          );





        console.log(
          "UPDATED:",
          response.data
        );





        const updatedOrders =
          orders.map((order) =>

            order._id ===
            orderId

              ? {

                  ...order,

                  orderStatus:
                    newStatus
                }

              : order
          );





        setOrders(
          updatedOrders
        );





        if (

          selectedOrder &&

          selectedOrder._id ===
          orderId

        ) {

          setSelectedOrder({

            ...selectedOrder,

            orderStatus:
              newStatus
          });
        }

      } catch (error) {

        console.log(
          "Status Update Error:",
          error
        );
      }
    };





  // =========================================
  // DELETE ORDER
  // =========================================

  const deleteOrder =
    async (orderId) => {

      const confirmDelete =
        window.confirm(

          "🗑 Are you sure you want to delete this order?"
        );





      if (!confirmDelete)
        return;





      try {

        await axios.delete(

          `https://cvru-cms.onrender.com/api/v1/orders/admin/delete-order/${orderId}`,

          {
            withCredentials: true
          }
        );





        const updatedOrders =
          orders.filter(

            (order) =>

              order._id !==
              orderId
          );





        setOrders(
          updatedOrders
        );





        if (
          updatedOrders.length > 0
        ) {

          setSelectedOrder(

            updatedOrders[0]
          );

        } else {

          setSelectedOrder(
            null
          );
        }





        alert(
          "✅ Order deleted successfully"
        );

      } catch (error) {

        console.log(
          "Delete Error:",
          error
        );

        alert(
          "❌ Failed to delete order"
        );
      }
    };





  // =========================================
  // TOTAL REVENUE
  // =========================================

  const totalRevenue =
    orders.reduce(

      (acc, order) =>

        acc +
        (order.totalAmount || 0),

      0
    );





  // =========================================
  // STATUS CLASS
  // =========================================

  const getStatusClass =
    (status) => {

      switch (status) {

        case "delivered":
          return "delivered";

        case "cancelled":
          return "cancelled";

        case "preparing":
          return "preparing";

        default:
          return "pending";
      }
    };





  // =========================================
  // STATUS ICON
  // =========================================

  // eslint-disable-next-line no-unused-vars
  const getStatusIcon =
    (status) => {

      switch (status) {

        case "delivered":
          return <FaCheckCircle />;

        case "cancelled":
          return <FaTimesCircle />;

        case "preparing":
          return <FaUtensils />;

        default:
          return <FaClock />;
      }
    };





  return (

    <div

      className="admin-orders-page"

      style={{

        backgroundImage:
          `url(${bgImage})`,

        backgroundSize:
          "cover",

        backgroundPosition:
          "center"
      }}
    >



      {/* ========================================= */}
      {/* TOP STATS */}
      {/* ========================================= */}

      <div className="orders-stats">

        <div className="stat-card">

          <div className="stat-icon purple">
            🛒
          </div>

          <div>

            <p>
              Orders
            </p>

            <h2>
              {orders.length}
            </h2>

          </div>

        </div>





        <div className="stat-card">

          <div className="stat-icon gold">
            ⭐
          </div>

          <div>

            <p>
              Delivered
            </p>

            <h2>

              {

                orders.filter(

                  (o) =>
                    o.orderStatus ===
                    "delivered"

                ).length
              }

            </h2>

          </div>

        </div>





        <div className="stat-card">

          <div className="stat-icon pink">
            💲
          </div>

          <div>

            <p>
              Revenue
            </p>

            <h2>

              ₹{totalRevenue}

            </h2>

          </div>

        </div>





        <div className="stat-card">

          <div className="stat-icon red">
            ⏳
          </div>

          <div>

            <p>
              Pending
            </p>

            <h2>

              {

                orders.filter(

                  (o) =>
                    o.orderStatus ===
                    "placed"

                ).length
              }

            </h2>

          </div>

        </div>

      </div>









      {/* ========================================= */}
      {/* MAIN CONTAINER */}
      {/* ========================================= */}

      <div className="orders-container">



        {/* ========================================= */}
        {/* LEFT PANEL */}
        {/* ========================================= */}

        <div className="orders-left">

          <h2 className="orders-heading">

            Food Orders

          </h2>





          <div className="orders-header">

            <span>#</span>

            <span>User</span>

            <span>Token</span>

            <span>Total</span>

            <span>Status</span>

          </div>





          {

            loading ? (

              <p>

                Loading...

              </p>

            ) : (

              orders.map(

                (
                  order,
                  index
                ) => (

                  <div

                    className="order-row"

                    key={order._id}

                    onClick={() =>
                      setSelectedOrder(order)
                    }
                  >

                    <span>

                      {index + 1}

                    </span>





                    <span>

                      {

                        order.user?.userName ||

                        order.user?.fullName ||

                        "User"
                      }

                    </span>





                    <span>

                      #

                      {

                        order.tokenNumber ||

                        "----"
                      }

                    </span>





                    <span>

                      ₹

                      {

                        order.totalAmount || 0
                      }

                    </span>





                    <span

                      className={`status ${

                        getStatusClass(
                          order.orderStatus
                        )
                      }`}
                    >

                      {

                        order.orderStatus
                      }

                    </span>

                  </div>
                )
              )
            )
          }

        </div>









        {/* ========================================= */}
        {/* RIGHT PANEL */}
        {/* ========================================= */}

        <div className="orders-right">

          {

            selectedOrder ? (

              <>

                {/* HEADER */}

                <div className="details-header">

                  <h2>

                    🍽 Order Details

                  </h2>





                  <div className="token-box">

                    Token #

                    {

                      selectedOrder.tokenNumber
                    }

                  </div>

                </div>









                {/* LIVE STATUS */}

                <div

                  className={`live-status ${selectedOrder.orderStatus}`}
                >

                  {

                    selectedOrder.orderStatus ===
                    "placed"

                      ? "🟡 Order Placed"

                      : selectedOrder.orderStatus ===
                        "preparing"

                      ? "👨‍🍳 Preparing"

                      : selectedOrder.orderStatus ===
                        "delivered"

                      ? "✅ Delivered"

                      : "❌ Cancelled"
                  }

                </div>









                {/* ITEMS */}

                <div className="items-wrapper">

                  {

                    selectedOrder.items?.map(

                      (
                        item,
                        i
                      ) => (

                        <div

                          className="modern-item-card"

                          key={i}
                        >

                          <div className="food-icon">

                            🍔

                          </div>





                          <div className="food-details">

                            <h3>

                              {

                                item.name ||

                                item.food?.name ||

                                "Food Item"
                              }

                            </h3>





                            <p>

                              Quantity :

                              {

                                item.quantity || 1
                              }

                            </p>

                          </div>





                          <div className="food-price">

                            ₹

                            {

                              (

                                item.price ||

                                item.food?.price ||

                                0

                              ) *

                              (

                                item.quantity || 1
                              )
                            }

                          </div>

                        </div>
                      )
                    )
                  }

                </div>









                {/* TOTAL */}

                <div className="modern-total-box">

                  <span>

                    Grand Total

                  </span>





                  <h2>

                    ₹

                    {

                      selectedOrder.totalAmount || 0
                    }

                  </h2>

                </div>









                {/* STATUS TRACKER */}

                <div className="live-status-wrapper">



                  {/* PLACED */}

                  <div className="status-step">

                    <div

                      className={`status-circle ${

                        selectedOrder.orderStatus === "placed" ||

                        selectedOrder.orderStatus === "preparing" ||

                        selectedOrder.orderStatus === "delivered"

                          ? "active-circle"

                          : ""
                      }`}
                    >

                      <FaClipboardList />

                    </div>





                    <p className="active-text">

                      Placed

                    </p>

                  </div>









                  <div

                    className={`status-bar ${

                      selectedOrder.orderStatus === "preparing" ||

                      selectedOrder.orderStatus === "delivered"

                        ? "active-bar"

                        : ""
                    }`}
                  ></div>









                  {/* PREPARING */}

                  <div className="status-step">

                    <div

                      className={`status-circle ${

                        selectedOrder.orderStatus === "preparing" ||

                        selectedOrder.orderStatus === "delivered"

                          ? "active-circle"

                          : ""
                      }`}
                    >

                      <FaUtensils />

                    </div>





                    <p

                      className={`status-text ${

                        selectedOrder.orderStatus === "preparing" ||

                        selectedOrder.orderStatus === "delivered"

                          ? "active-text"

                          : ""
                      }`}
                    >

                      Preparing

                    </p>

                  </div>









                  <div

                    className={`status-bar ${

                      selectedOrder.orderStatus === "delivered"

                        ? "active-bar"

                        : ""
                    }`}
                  ></div>









                  {/* DELIVERED */}

                  <div className="status-step">

                    <div

                      className={`status-circle ${

                        selectedOrder.orderStatus === "delivered"

                          ? "active-circle"

                          : ""
                      }`}
                    >

                      <FaCheckCircle />

                    </div>





                    <p

                      className={`status-text ${

                        selectedOrder.orderStatus === "delivered"

                          ? "active-text"

                          : ""
                      }`}
                    >

                      Delivered

                    </p>

                  </div>

                </div>









                {/* STATUS UPDATE */}

                <div className="modern-status-section">

                  <h3>

                    Update Order Status

