@import "tailwindcss";
/* =========================================
GLOBAL SMOOTHNESS
========================================= */

* {

  margin: 0;

  padding: 0;

  box-sizing: border-box;

  transition:
    all 0.3s ease;
}



/* =========================================
BODY ANIMATION
========================================= */

body {

  background: #0f172a;

  overflow-x: hidden;

  animation:
    pageFade 1s ease;
}



/* =========================================
PAGE FADE
========================================= */

@keyframes pageFade {

  from {

    opacity: 0;

    transform: translateY(20px);
  }

  to {

    opacity: 1;

    transform: translateY(0);
  }
}



/* =========================================
FLOATING EFFECT
========================================= */

@keyframes floating {

  0% {

    transform: translateY(0px);
  }

  50% {

    transform: translateY(-8px);
  }

  100% {

    transform: translateY(0px);
  }
}



/* =========================================
GLOW PULSE
========================================= */

@keyframes glowPulse {

  0% {

    box-shadow:
      0 0 5px rgba(255, 204, 0, 0.2);
  }

  50% {

    box-shadow:
      0 0 25px rgba(255, 204, 0, 0.5);
  }

  100% {

    box-shadow:
      0 0 5px rgba(255, 204, 0, 0.2);
  }
}



/* =========================================
SLIDE IN
========================================= */

@keyframes slideUp {

  from {

    opacity: 0;

    transform: translateY(40px);
  }

  to {

    opacity: 1;

    transform: translateY(0);
  }
}



/* =========================================
BUTTON POP
========================================= */

@keyframes buttonPop {

  0% {

    transform: scale(1);
  }

  50% {

    transform: scale(1.06);
  }

  100% {

    transform: scale(1);
  }
}



/* =========================================
CARD ANIMATION
========================================= */

.food-card,

.stat-card,

.modern-order-card,

.history-card,

.cart-container-box,

.order-container-box {

  animation:
    slideUp 0.6s ease;

  backdrop-filter: blur(10px);
}



/* =========================================
CARD HOVER
========================================= */

.food-card:hover,

.stat-card:hover,

.modern-order-card:hover,

.history-card:hover {

  transform:
    translateY(-8px)
    scale(1.02);

  box-shadow:
    0 14px 28px rgba(0,0,0,0.35);
}



/* =========================================
BUTTON EFFECT
========================================= */

button {

  position: relative;

  overflow: hidden;
}



/* BUTTON HOVER */

button:hover {

  animation:
    buttonPop 0.4s ease;
}



/* =========================================
GLOW EFFECT BUTTONS
========================================= */

.add-btn,

.place-order-btn,

.auth-btn {

  animation:
    glowPulse 2s infinite;
}



/* =========================================
IMAGE FLOAT
========================================= */

.food-image,

.banner-image {

  animation:
    floating 4s ease-in-out infinite;
}



/* =========================================
INPUT EFFECT
========================================= */

input {

  transition:
    0.3s ease;
}



/* INPUT FOCUS */

input:focus {

  transform: scale(1.02);

  box-shadow:
    0 0 15px rgba(255, 204, 0, 0.35);
}



/* =========================================
SCROLLBAR
========================================= */

::-webkit-scrollbar {

  width: 8px;
}



::-webkit-scrollbar-track {

  background: #0f172a;
}



::-webkit-scrollbar-thumb {

  background: linear-gradient(
    #ffcc00,
    #ff9900
  );

  border-radius: 10px;
}



/* =========================================
TEXT GRADIENT
========================================= */

.orders-title,

.section-title,

.food-name,

.logo-text {

  background: linear-gradient(
    90deg,
    #ffcc00,
    #ff9900
  );

  -webkit-background-clip: text;

  -webkit-text-fill-color: transparent;
}



/* =========================================
NOTIFICATION POPUP EFFECT
========================================= */

.Toastify__toast {

  border-radius: 14px;

  backdrop-filter: blur(10px);

  animation:
    slideUp 0.4s ease;
}

