import React from "react";

import { useNavigate } from "react-router-dom";

function Cart({

  cart,

  increaseQty,

  decreaseQty,

  // eslint-disable-next-line no-unused-vars
  setCart

}) {

  // ======================================
  // NAVIGATE
  // ======================================

  const navigate =
    useNavigate();




  // ======================================
  // SUBTOTAL
  // ======================================

  const subTotal =
    cart.reduce(

      (total, item) =>

        total +

        item.price * item.quantity,

      0
    );




  // ======================================
  // GO TO PAYMENT PAGE
  // ======================================

  const handlePlaceOrder =
    () => {

      // EMPTY CART
      if (cart.length === 0) {

        alert(
          "Your cart is empty!"
        );

        return;
      }




      // NAVIGATE TO PAYMENT
      navigate(

        "/payment",

        {

          state: {

            total:
              subTotal,

            cart
          }
        }
      );
    };




  return (

    <div

      className="cart-sidebar"

      style={{

        width: "360px",

        display: "flex",

        flexDirection: "column",

        gap: "24px",

        padding: "10px",

        fontFamily:
          "'Segoe UI', Roboto, sans-serif"
      }}
    >




      {/* ====================================== */}
      {/* MY CART */}
      {/* ====================================== */}

      <div

        className="cart-container-box"

        style={{

          background: "#0d1527",

          borderRadius: "16px",

          padding: "24px",

          border:
            "1px solid rgba(255, 255, 255, 0.05)",

          minHeight: "220px",

          display: "flex",

          flexDirection: "column",

          boxShadow:
            "0 10px 25px rgba(0,0,0,0.3)"
        }}
      >




        <h3

          style={{

            color: "#ffffff",

            fontSize: "1.3rem",

            margin:
              "0 0 20px 0",

            fontWeight: "600",

            letterSpacing:
              "0.5px"
          }}
        >

          My Cart

        </h3>





        {

          cart.length === 0

          ? (

            <div

              style={{

                display: "flex",

                flexGrow: 1,

                alignItems: "center",

                justifyContent: "center"
              }}
            >

              <p

                className="no-items"

                style={{

                  color: "#475569",

                  fontSize: "0.95rem"
                }}
              >

                No items selected

              </p>

            </div>

          ) : (

            <div

              className="cart-items-list"

              style={{

                display: "flex",

                flexDirection: "column",

                gap: "16px",

                maxHeight: "280px",

                overflowY: "auto"
              }}
            >

              {

                cart.map((item) => {

                  const itemId =

                    item._id ||

                    item.id;




                  return (

                    <div

                      key={itemId}

                      className="cart-item-row"

                      style={{

                        display: "flex",

                        alignItems: "center",

                        justifyContent:
                          "space-between",

                        paddingBottom: "14px",

                        borderBottom:
                          "1px solid rgba(255, 255, 255, 0.04)"
                      }}
                    >




                      {/* QUANTITY */}

                      <div

                        className="qty-box"

                        style={{

                          display: "flex",

                          alignItems: "center",

                          gap: "12px",

                          background: "#1e293b",

                          padding: "6px 10px",

                          borderRadius: "8px"
                        }}
                      >




                        <button

                          onClick={() =>

                            decreaseQty(itemId)
                          }

                          style={{

                            background:
                              "transparent",

                            color: "#ffc72c",

                            border: "none",

                            fontWeight: "bold",

