          </span>

          <span

            style={{

              color: "#ffffff",

              fontWeight: "600"
            }}
          >

            ₹ {subTotal}

          </span>

        </div>





        <hr

          style={{

            border: "none",

            borderTop:
              "1px solid rgba(255, 255, 255, 0.08)",

