          }}
        />





        {/* GRAND TOTAL */}

        <div

          className="order-row grand-total-row"

          style={{

            display: "flex",

            justifyContent:
              "space-between",

            alignItems: "center",

            margin:
              "16px 0 24px 0"
          }}
        >




          <span

            className="grand-total-lbl"

            style={{

              color: "#ffffff",

              fontWeight: "600",

              fontSize: "1.1rem"
            }}
          >

