          </span>





          <span

            className="grand-total-val"

            style={{

              color: "#ffc72c",

              fontWeight: "700",

              fontSize: "1.6rem",

              letterSpacing:
                "0.5px"
            }}
          >

            ₹ {subTotal}

          </span>

        </div>





        {/* BUTTON */}

        <button

          className="place-order-btn"

          onClick={handlePlaceOrder}

          style={{

            width: "100%",

