files.client/src/css/Orders.css:
/* =========================================
   GOOGLE FONT
========================================= */

@import url("https://fonts.googleapis.com/css2?family=Poppins:wght@300;400;500;600;700&display=swap");



/* =========================================
   MAIN PAGE
========================================= */

.orders-page {
  min-height: 100vh;
  background: linear-gradient(
    to bottom right,
    #f5f7fb,
    #eef2ff
  );

  padding: 25px;
  font-family: "Poppins", sans-serif;
}



/* =========================================
   HEADER
========================================= */

.orders-header {
  background: linear-gradient(
    135deg,
    #ffcc00,
    #ff9f1a
  );

  border-radius: 24px;

  padding: 35px;

  display: flex;
  justify-content: space-between;
  align-items: center;

  box-shadow:
    0 12px 30px rgba(0,0,0,0.08);

  position: relative;
  overflow: hidden;

  margin-bottom: 35px;
}

.orders-header::before {
  content: "";

  position: absolute;

  width: 250px;
  height: 250px;

  background: rgba(255,255,255,0.15);

  border-radius: 50%;

  top: -80px;
  right: -80px;
}

.orders-title {
  font-size: 42px;
  font-weight: 700;
  color: #111;
}

.orders-subtitle {
  margin-top: 8px;
  color: #333;
  font-size: 16px;
}



/* =========================================
   BACK BUTTON
========================================= */

.back-btn {
  position: fixed;

  top: 20px;
  left: 20px;

  width: 48px;
  height: 48px;

  border: none;
  border-radius: 50%;

  background: white;

  color: #111;

  font-size: 18px;

  display: flex;
  justify-content: center;
  align-items: center;

  cursor: pointer;

  z-index: 999;

  box-shadow:
    0 5px 18px rgba(0,0,0,0.15);

  transition: 0.3s;
}

.back-btn:hover {
  transform: translateY(-2px);
  background: #ffcc00;
}



/* =========================================
   SECTION TITLE
========================================= */
.section-title h2{
  color: red;
}

.section-title {
  font-size: 28px;
  font-weight: 700;
  color: red;
  margin-bottom: 20px;
}


/* =========================================
   CURRENT ORDER CARD
========================================= */

.modern-order-card {
  background: white;

  border-radius: 24px;

  padding: 28px;

  margin-bottom: 30px;

  box-shadow:
    0 10px 25px rgba(0,0,0,0.06);

  transition: 0.3s;
}

.modern-order-card:hover {
  transform: translateY(-3px);
}



/* =========================================
   CARD TOP
========================================= */

.order-card-top {
  display: flex;
  justify-content: space-between;
  align-items: center;

  margin-bottom: 22px;
}

.order-card-top h3 {
  font-size: 28px;
  color: #111;
  margin-bottom: 6px;
}

.order-card-top p {
  color: #777;
  font-size: 14px;
}



/* =========================================
   STATUS BADGE
========================================= */

.status-pill {
  padding: 10px 18px;

  border-radius: 30px;

  font-size: 14px;
  font-weight: 600;

  text-transform: capitalize;

  box-shadow:
    0 3px 10px rgba(0,0,0,0.08);
}

.status-pill.placed {
  background: #fff3cd;
  color: #ff9800;
}

.status-pill.preparing {
  background: #d6ecff;
  color: #007bff;
}

.status-pill.delivered {
  background: #d4f8dd;
  color: #28a745;
}



/* =========================================
   ITEMS
========================================= */

.order-items {
  margin-top: 15px;
}

.order-item-row {
  display: flex;
  justify-content: space-between;
  align-items: center;

  padding: 18px 0;

  border-bottom:
    1px solid #f0f0f0;
}

.order-item-row:last-child {
  border-bottom: none;
}

.order-item-row h4 {
  font-size: 18px;
  color: #222;
}

.order-item-row p {
  margin-top: 4px;
  color: #777;
  font-size: 14px;
}

.order-item-row span {
  font-size: 18px;
  font-weight: 700;
  color: #ff9800;
}



/* =========================================
   TOTAL
========================================= */

.order-total {
  margin-top: 25px;

  background: linear-gradient(
    135deg,
    #ff9800,
    #fff1cc
  );

  border-radius: 18px;

  padding: 20px 22px;

  display: flex;
  justify-content: space-between;
  align-items: center;
}

.order-total h3 {
  font-size: 18px;
  color: #333;
}

.order-total span {
  font-size: 28px;
  font-weight: 700;
  color: #ff9800;
}



/* =========================================
   STATUS TRACKER
========================================= */

.status-tracker {
  display: flex;
  justify-content: center;
  align-items: center;

  margin-top: 35px;
}

.status-item {
  display: flex;
  flex-direction: column;
  align-items: center;

  position: relative;
}

.status-icon {
  width: 65px;
  height: 65px;

  border-radius: 50%;

  background: #ddd;

  color: white;

  display: flex;
  align-items: center;
  justify-content: center;

  font-size: 24px;

  transition: 0.4s;
}

.status-icon.active {
  background: linear-gradient(
    135deg,
    #ffb300,
    #ff9800
  );

  box-shadow:
    0 5px 18px rgba(255,152,0,0.35);
}

.status-item p {
  margin-top: 10px;

  font-size: 14px;
  font-weight: 600;

  color: #555;
}

.status-line {
  width: 100px;
  height: 5px;

  border-radius: 20px;

  background: #ddd;

  margin: 0 12px;
}



/* =========================================
   HISTORY CARDS
========================================= */

.history-card {
  background: white;

  border-radius: 20px;

  padding: 24px;

  margin-bottom: 20px;

  box-shadow:
    0 6px 18px rgba(0,0,0,0.05);

  transition: 0.3s;
}

.history-card:hover {
  transform: translateY(-2px);
}

.history-top {
  display: flex;
  justify-content: space-between;
  align-items: center;

  margin-bottom: 18px;
}

.history-top h3 {
  font-size: 22px;
  color: #222;
}

.history-top p {
  font-size: 14px;
  color: #777;
}



/* =========================================
   HISTORY ITEMS
========================================= */

.history-item {
  display: flex;
  justify-content: space-between;

  padding: 12px 0;

  border-bottom:
    1px solid #f0f0f0;
}

.history-total {
  margin-top: 18px;

  text-align: right;

  font-size: 24px;
  font-weight: 700;

  color: #ff9800;
}



/* =========================================
   EMPTY BOX
========================================= */

.empty-box {
  background: white;

  padding: 50px;

  border-radius: 20px;

  text-align: center;

  color: #888;

  box-shadow:
    0 5px 15px rgba(0,0,0,0.05);
}

.empty-box svg {
  color: #ffb300;
}

.empty-box p {
  margin-top: 12px;
  font-size: 18px;
}



/* =========================================
   RESPONSIVE
========================================= */

@media (max-width: 768px) {

  .orders-page {
    padding: 15px;
  }

  .orders-header {
    flex-direction: column;
    align-items: flex-start;
    gap: 10px;
  }

  .orders-title {
    font-size: 32px;
  }

  .order-card-top {
    flex-direction: column;
    align-items: flex-start;
    gap: 15px;
  }

  .status-tracker {
    flex-direction: column;
    gap: 18px;
  }

