    to right,
    #ffb300,
    #ff9800
  );
}



/* PULSE ANIMATION */

@keyframes pulseStatus {

  0% {
    transform: scale(1);
    box-shadow:
      0 0 0 0 rgba(255, 179, 0, 0.4);
  }

  70% {
    transform: scale(1.08);
    box-shadow:
      0 0 0 14px rgba(255, 179, 0, 0);
  }

  100% {
    transform: scale(1);
    box-shadow:
      0 0 0 0 rgba(255, 179, 0, 0);
  }
}

.status-icon.active {
  animation: pulseStatus 2s infinite;
}
/* =========================================
   ACTIVE ICON HIGHLIGHT
========================================= */

.status-icon.active {
  background: linear-gradient(
    135deg,
    #ffcc00,
    #ff9800
  );

  color: white;

  border: 4px solid white;

  box-shadow:
    0 0 0 6px rgba(255, 179, 0, 0.18),
