  transform: scale(1.12);

  animation: pulseStatus 1.8s infinite;
}



/* =========================================
   ACTIVE TEXT
========================================= */

.status-item.active-status p {
  color: #ff9800;
  font-weight: 700;
  font-size: 15px;
}



/* =========================================
   ACTIVE LINE
========================================= */

.status-line.active-line {
  background: linear-gradient(
    to right,
    #ffcc00,
    #ff9800
  );

  box-shadow:
    0 2px 8px rgba(255, 152, 0, 0.3);
}



/* =========================================
   ICON HOVER EFFECT
========================================= */

.status-icon:hover {
  transform: scale(1.15);
  transition: 0.3s ease;
}



/* =========================================
   PULSE EFFECT
========================================= */

@keyframes pulseStatus {

  0% {
    box-shadow:
      0 0 0 0 rgba(255, 179, 0, 0.45),
      0 10px 24px rgba(255, 152, 0, 0.35);
  }

  70% {
    box-shadow:
      0 0 0 16px rgba(255, 179, 0, 0),
