  position: relative;
  top: -15px; /* Adjust based on your alignment layout */
  transition: background-color 0.4s ease;
}


/* --- Active Status Styles (Triggered via Admin Socket) --- */

/* 1. Turns the circle container background color (e.g., Orange/Green theme) */
.status-circle.active-circle {
  background-color: #ff9f43; /* Active orange accent container */
  box-shadow: 0 0 12px rgba(255, 159, 67, 0.4);
  transform: scale(1.1);
}

/* 2. Direct target to change the internal React Icon's color to white/bright when active */
.status-circle.active-circle svg {
