.token-page {

  min-height: 100vh;

  background:
    linear-gradient(
      135deg,
      #0f172a,
      #111827,
      #1e293b
    );

  display: flex;

  justify-content: center;

  align-items: center;

  padding: 30px;

  position: relative;

  overflow: hidden;
}



.token-card {

  width: 100%;

  max-width: 520px;

  background:
    rgba(30, 41, 59, 0.95);

  border-radius: 30px;

  padding: 40px;

  text-align: center;

  box-shadow:
    0 20px 50px rgba(0,0,0,0.45);

  border:
    1px solid rgba(255,255,255,0.05);

  animation:
    fadeUp 0.5s ease;
}



.success-icon {

  font-size: 80px;

  color: #22c55e;

  margin-bottom: 20px;

  animation:
    popScale 1s ease;
}



.success-title {

  color: white;

  font-size: 34px;

  margin-bottom: 10px;

  font-weight: 800;
}



.success-subtitle {

  color: #94a3b8;

  margin-bottom: 30px;

  font-size: 16px;
}



/* ======================================
TOKEN BOX
====================================== */

.token-box {

  background:
    linear-gradient(
      135deg,
      #1e293b,
      #0f172a
    );

  padding: 35px;

  border-radius: 24px;

  margin: 25px 0;

  border:
    2px dashed #ffd000;

  box-shadow:
    0 10px 30px rgba(0,0,0,0.4);
}



.token-title {

  color: #94a3b8;

  font-size: 18px;

  margin-bottom: 20px;

  font-weight: 600;
}



.token-number {

  font-size: 48px;

  font-weight: 900;

  color: white;

  letter-spacing: 4px;

  text-shadow:
    0 0 15px rgba(255,208,0,0.5);

  animation:
    pulseToken 1.5s infinite;
}



.token-wait {

  margin-top: 18px;

  color: #e61919;

  font-size: 15px;
}



/* ======================================
DETAILS
====================================== */

.token-details {

  display: grid;

  grid-template-columns:
    repeat(2, 1fr);

  gap: 18px;

  margin-top: 30px;
}



.detail-item {

  background: #1e293b;

  padding: 18px;

  border-radius: 18px;

  display: flex;

  align-items: center;

  gap: 14px;

  text-align: left;

  transition: 0.3s ease;
}



.detail-item:hover {

  transform:
    translateY(-4px);

  box-shadow:
    0 10px 25px rgba(0,0,0,0.3);
}



.detail-item svg {

  font-size: 28px;

  color: #ffd000;
}



.detail-item span {

  color: #94a3b8;

  font-size: 13px;
}



.detail-item h4 {

  color: white;

  margin-top: 4px;

  font-size: 16px;
}



/* ======================================
NOTE
====================================== */

.note-box {

  margin-top: 28px;

  background:
    rgba(255,208,0,0.1);

  color: #ffd000;

  padding: 15px;

  border-radius: 14px;

  font-size: 14px;

  font-weight: 600;
}



/* ======================================
BACK BUTTON
====================================== */

.back-btn {

  position: absolute;

  top: 30px;

  left: 30px;

  width: 50px;

  height: 50px;

  border-radius: 50%;

  border: none;

  background: #ffd000;

  color: #111827;

  display: flex;

  justify-content: center;

  align-items: center;

  cursor: pointer;

  font-size: 18px;

  transition: 0.3s ease;
}



.back-btn:hover {

  transform:
    scale(1.1);
}



/* ======================================
ANIMATIONS
====================================== */

@keyframes pulseToken {

  0% {

    transform: scale(1);
  }

  50% {

    transform: scale(1.05);
  }

  100% {

    transform: scale(1);
  }
}



@keyframes popScale {

  0% {

    transform: scale(0);
  }

  100% {

    transform: scale(1);
  }
}



@keyframes fadeUp {

  from {

    opacity: 0;

    transform:
      translateY(30px);
  }

  to {

    opacity: 1;

    transform:
      translateY(0);
  }
}



/* ======================================
RESPONSIVE
====================================== */

@media screen and (max-width: 768px) {

  .token-card {

    padding: 25px;
  }



  .token-details {

    grid-template-columns: 1fr;
  }



  .token-number {

    font-size: 36px;
  }



  .success-title {

    font-size: 28px;
  }
}

