  --text: #6b6375;
  --text-h: #08060d;
  --bg: #fff;
  --border: #e5e4e7;
  --code-bg: #f4f3ec;
  --accent: #aa3bff;
  --accent-bg: rgba(170, 59, 255, 0.1);
  --accent-border: rgba(170, 59, 255, 0.5);
  --social-bg: rgba(244, 243, 236, 0.5);
  --shadow:
    rgba(0, 0, 0, 0.1) 0 10px 15px -3px, rgba(0, 0, 0, 0.05) 0 4px 6px -2px;

  --sans: system-ui, 'Segoe UI', Roboto, sans-serif;
  --heading: system-ui, 'Segoe UI', Roboto, sans-serif;
  --mono: ui-monospace, Consolas, monospace;

  font: 18px/145% var(--sans);
  letter-spacing: 0.18px;
  color-scheme: light dark;
  color: var(--text);
  background: var(--bg);
  font-synthesis: none;
  text-rendering: optimizeLegibility;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;

  @media (max-width: 1024px) {
    font-size: 16px;
  }
}
* {

  max-width: 100%;
}
@media (prefers-color-scheme: dark) {
  :root {
    --text: #9ca3af;
    --text-h: #f3f4f6;
    --bg: #16171d;
    --border: #2e303a;
    --code-bg: #1f2028;
    --accent: #c084fc;
    --accent-bg: rgba(192, 132, 252, 0.15);
    --accent-border: rgba(192, 132, 252, 0.5);
    --social-bg: rgba(47, 48, 58, 0.5);
    --shadow:
      rgba(0, 0, 0, 0.4) 0 10px 15px -3px, rgba(0, 0, 0, 0.25) 0 4px 6px -2px;
  }

  #social .button-icon {
    filter: invert(1) brightness(2);
  }
}

body {
  margin: 0;
}

#root {
  width: 1126px;
  max-width: 100%;
  margin: 0 auto;
  text-align: center;
  border-inline: 1px solid var(--border);
  min-height: 100svh;
  display: flex;
  flex-direction: column;
  box-sizing: border-box;
}
*{
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}



html,
body,
#root{
  width: 100%;
  min-height: 100vh;

  overflow-x: hidden;

  background: #000f4d;
}



body{
  font-family: sans-serif;
}
h1,
h2 {
  font-family: var(--heading);
  font-weight: 500;
  color: var(--text-h);
}

h1 {
  font-size: 56px;
  letter-spacing: -1.68px;
  margin: 32px 0;
  @media (max-width: 1024px) {
    font-size: 36px;
    margin: 20px 0;
  }
}
h2 {
  font-size: 24px;
  line-height: 118%;
  letter-spacing: -0.24px;
  margin: 0 0 8px;
  @media (max-width: 1024px) {
    font-size: 20px;
  }
}
p {
  margin: 0;
}

code,
.counter {
  font-family: var(--mono);
  display: inline-flex;
  border-radius: 4px;
  color: var(--text-h);
}

code {
  font-size: 15px;
  line-height: 135%;
  padding: 4px 8px;
  background: var(--code-bg);
}
/* TOAST POPUP */

.Toastify__toast {

  border-radius: 16px;

  font-weight: 600;

  font-size: 14px;
}



.Toastify__toast--success {

  background: #16a34a;
}



.Toastify__toast--info {

  background: #2563eb;
}



/* =========================================
FORCE GLOBAL UI FIX
========================================= */

html,

body,

#root {

  width: 100%;

  min-height: 100vh;

  background: #0f172a;

  overflow-x: hidden;

  scroll-behavior: smooth;
}



/* =========================================
GLOBAL ANIMATION
========================================= */

body {

  animation:
    smoothPage 1s ease;

  font-family:
    "Poppins",
    sans-serif;
}



/* =========================================
KEYFRAMES
========================================= */

@keyframes smoothPage {

  from {

    opacity: 0;

    transform: scale(0.98);
  }

  to {

    opacity: 1;

    transform: scale(1);
  }
}



@keyframes fadeUp {

  from {

    opacity: 0;

    transform: translateY(40px);
  }

  to {

    opacity: 1;

    transform: translateY(0);
  }
}



@keyframes floating {

  0% {

    transform: translateY(0px);
  }

  50% {

    transform: translateY(-10px);
  }

  100% {

    transform: translateY(0px);
  }
}



@keyframes glow {

  0% {

    box-shadow:
      0 0 10px rgba(255,204,0,0.2);
  }

  50% {

    box-shadow:
      0 0 25px rgba(255,204,0,0.5);
  }

  100% {

    box-shadow:
      0 0 10px rgba(255,204,0,0.2);
  }
}



/* =========================================
ALL CONTAINERS
========================================= */

.dashboard,

.food-card,

.modern-order-card,

.history-card,

.cart-container-box,

.order-container-box,

.stat-card,

.sidebar,

.navbar {

  animation:
    fadeUp 0.7s ease;

  transition:
    all 0.3s ease;
}



/* =========================================
CARD HOVER
========================================= */

.food-card:hover,

.modern-order-card:hover,

.history-card:hover,

.stat-card:hover {

  transform:
    translateY(-8px)
    scale(1.02);

  box-shadow:
    0 12px 24px rgba(0,0,0,0.35);
}



/* =========================================
BUTTONS
========================================= */

button {

  transition:
    all 0.3s ease;

  cursor: pointer;
}



/* BUTTON HOVER */

button:hover {

  transform:
    translateY(-2px);

  filter: brightness(1.08);
}



/* BUTTON CLICK */

button:active {

  transform:
    scale(0.96);
}



/* =========================================
PREMIUM BUTTON GLOW
========================================= */

.add-btn,

.place-order-btn,

.auth-btn {

  animation:
    glow 2s infinite;
}



/* =========================================
FOOD IMAGE FLOATING
========================================= */

.food-image {

  animation:
    floating 4s ease-in-out infinite;
}



/* =========================================
INPUT FIX
========================================= */

input,

textarea {

  color: white !important;

  -webkit-text-fill-color: white !important;

  background:
    rgba(255,255,255,0.08) !important;

  border:
    1px solid rgba(255,255,255,0.12) !important;

  transition:
    0.3s ease;
}



/* INPUT PLACEHOLDER */

input::placeholder,

textarea::placeholder {

  color: #cbd5e1 !important;
}



/* INPUT FOCUS */

input:focus,

textarea:focus {

  outline: none;

  border:
    1px solid #ffcc00 !important;

  box-shadow:
    0 0 15px rgba(255,204,0,0.3);

  transform:
    scale(1.02);
}



/* =========================================
AUTOFILL FIX
========================================= */

input:-webkit-autofill,

input:-webkit-autofill:hover,

input:-webkit-autofill:focus {

  -webkit-text-fill-color:
    white !important;

  transition:
    background-color 9999s ease-in-out 0s;

  box-shadow:
    0 0 0px 1000px #1e293b inset !important;
}



/* =========================================
SCROLLBAR
========================================= */

::-webkit-scrollbar {

  width: 8px;
}



::-webkit-scrollbar-track {

  background: #0f172a;
}



::-webkit-scrollbar-thumb {

  background:
    linear-gradient(
      #ffcc00,
      #ff9900
    );

  border-radius: 10px;
}



/* =========================================
TEXT ENHANCEMENT
========================================= */

h1,

h2,

h3,

.logo-text {

  letter-spacing: 0.5px;
}



/* =========================================
TOASTIFY
========================================= */

.Toastify__toast {

  border-radius: 14px;

  animation:
    fadeUp 0.4s ease;
}
/* =========================================
GLOBAL RESPONSIVE FIX
========================================= */

html,

body,

#root {

  width: 100%;

  overflow-x: hidden;
}



/* =========================================
IMAGES RESPONSIVE
========================================= */

img {

  max-width: 100%;

  height: auto;

  object-fit: cover;
}



/* =========================================
BUTTON RESPONSIVE
========================================= */

button {

  min-height: 42px;
}



/* =========================================
FLEX WRAP
========================================= */

.dashboard-content,

.food-container,

.orders-container,

.orders-stats,

.cart-items-list {

  flex-wrap: wrap;
}



/* =========================================
FOOD GRID RESPONSIVE
========================================= */

.food-container {

  display: grid;

  grid-template-columns:
    repeat(
      auto-fit,
      minmax(260px, 1fr)
    );

  gap: 20px;
}



/* =========================================
FOOD CARD
========================================= */

.food-card {

  width: 100%;

  max-width: 320px;

  margin: auto;
}



/* =========================================
TABLET RESPONSIVE
========================================= */

@media screen and (max-width: 1024px) {

  .dashboard {

    flex-direction: column;
  }



  .dashboard-content {

    flex-direction: column;
  }



  .cart-sidebar {

    width: 100% !important;

    margin-top: 20px;
  }



  .food-section {

    width: 100%;
  }
}



/* =========================================
MOBILE RESPONSIVE
========================================= */

@media screen and (max-width: 768px) {

  .dashboard-main {

    padding: 10px;
  }



  .navbar {

    flex-direction: column;

    gap: 10px;
  }



  .food-container {

    grid-template-columns: 1fr;
  }



  .food-card {

    max-width: 100%;
  }



  .cart-sidebar {

    width: 100% !important;
  }



  .orders-container {

    flex-direction: column;
  }



  .orders-left,

  .orders-right {

    width: 100%;
  }



  .orders-stats {

    grid-template-columns:
      repeat(2, 1fr);

    gap: 10px;
  }



  .modern-order-card,

  .history-card {

    padding: 16px;
  }



  .status-tracker {

    flex-direction: column;

    gap: 14px;
  }



  .status-line {

    display: none;
  }



  .search-box input {

    width: 100%;
  }



  h1 {

    font-size: 1.8rem;
  }



  h2 {

    font-size: 1.4rem;
  }



  h3 {

    font-size: 1.1rem;
  }
}



/* =========================================
SMALL MOBILE
========================================= */

@media screen and (max-width: 480px) {

  .orders-stats {

    grid-template-columns: 1fr;
  }



  .stat-card {

    width: 100%;
  }



  .food-card {

    padding: 14px;
  }



  .place-order-btn,

  .add-btn {

    width: 100%;

    font-size: 14px;
  }



  .navbar {

    padding: 10px;
  }



  .sidebar {

    width: 100%;
  }
}

