/* eslint-disable react-hooks/set-state-in-effect */
import { useEffect, useState } from "react";

import socket from "../socket";

import "../css/Notifications.css";

function Notification() {

  const [notifications, setNotifications] =
    useState([]);





  // =====================================
  // LOAD OLD NOTIFICATIONS
  // =====================================

  useEffect(() => {

    const savedNotifications =
      JSON.parse(

        localStorage.getItem(
          "notifications"
        )
      ) || [];



    setNotifications(
      savedNotifications
    );

  }, []);





  // =====================================
  // SAVE NOTIFICATIONS
  // =====================================

  const saveNotification =
    (message) => {

      const newNotification = {

        id: Date.now(),

        message,

        time:
          new Date().toLocaleString()
      };



      setNotifications((prev) => {

        const updated = [

          newNotification,

          ...prev
        ];



        localStorage.setItem(

          "notifications",

          JSON.stringify(updated)
        );



        return updated;
      });
    };





  // =====================================
  // SOCKET EVENTS
  // =====================================

  useEffect(() => {

    // NEW ORDER
    socket.on(

      "newOrderPlaced",

      (order) => {

        saveNotification(

          `🛒 New order placed successfully! Token #${order.tokenNumber}`
        );
      }
    );





    // STATUS UPDATE
    socket.on(

      "orderStatusUpdated",

      (order) => {

        saveNotification(

          `📦 Your Order #${order.tokenNumber} is now ${order.orderStatus}`
        );
      }
    );





    return () => {

      socket.off(
        "newOrderPlaced"
      );

      socket.off(
        "orderStatusUpdated"
      );
    };

  }, []);





  return (

    <div className="notification-page">

      <h1>

        Notifications

      </h1>





      {

        notifications.length === 0 ? (

          <div className="empty-notification">

            No Notifications

          </div>

        ) : (

          notifications.map((item) => (

            <div

              className="notification-card"

              key={item.id}
            >

              <p>

                {item.message}

              </p>





              <span>

                {item.time}

              </span>

            </div>
          ))
        )
      }

    </div>
  );
}

export default Notification;

