/* eslint-disable no-undef */
/* eslint-disable react-hooks/set-state-in-effect */

import { useEffect, useState } from "react";
import { toast } from "react-toastify";
import {
  useNavigate,
} from "react-router-dom";

import axios from "axios";

import socket from "../socket";

import {
  FaArrowLeft,
  FaClipboardList,
  FaCheckCircle,
  FaUtensils,
  FaBoxOpen,
  FaClock,
  FaTimesCircle,
  FaShoppingBag
} from "react-icons/fa";

import "../css/Orders.css";

function Orders() {

  // =========================================
  // STATES
  // =========================================

  const [currentOrders, setCurrentOrders] =
    useState([]);

  const [historyOrders, setHistoryOrders] =
    useState([]);

  const [loading, setLoading] =
    useState(true);

  const navigate = useNavigate();





  // =========================================
  // BACK BUTTON
  // =========================================

  const handleBack = () => {

    navigate("/home");
  };





  // =========================================
  // FETCH ORDERS
  // =========================================

  const fetchMyOrders = async () => {

    try {

      const token =
        localStorage.getItem("token");





      const response =
        await axios.get(

          "https://cvru-cms.onrender.com/api/v1/orders/my-orders",

          {

            headers: {

              authorization:
                `Bearer ${token}`
            }
          }
        );





      const orders =
        response.data.orders || [];





      console.log(
        "MY ORDERS:",
        orders
      );





      if (orders.length > 0) {

        setCurrentOrders([
          orders[0]
        ]);

        setHistoryOrders(
          orders.slice(1)
        );

      } else {

        setCurrentOrders([]);
        setHistoryOrders([]);
      }

    } catch (error) {

      console.log(
        "FETCH ORDER ERROR:",
        error
      );

    } finally {

      setLoading(false);
    }
  };





  // =========================================
  // INITIAL FETCH
  // =========================================

  useEffect(() => {

    fetchMyOrders();

  }, []);





  // =========================================
  // SOCKET JOIN
  // =========================================

  useEffect(() => {

    const user =
      JSON.parse(
        localStorage.getItem("user")
      );





    if (user?._id) {

      socket.emit(
        "join",
        user._id
      );





      console.log(
        "Joined Socket Room:",
        user._id
      );
    }

  }, []);





  // =========================================
  // REALTIME SOCKET EVENTS
  // =========================================

  useEffect(() => {

    socket.on(

      "newOrder",

      (newOrder) => {

        console.log(
          "NEW ORDER:",
          newOrder
        );





        fetchMyOrders();
      }
    );





    socket.on(

      "newOrderPlaced",

      (data) => {
toast.success(

  `🛒 New Order Added! Token #${data.tokenNumber}`
);
        console.log(
          "NEW ORDER PLACED:",
          data
        );





        fetchMyOrders();
      }
    );





    socket.on(

      "orderUpdated",

      (updatedOrder) => {
toast.info(

  `📦 Order #${data.tokenNumber} is ${data.orderStatus}`
);
        console.log(
          "ORDER UPDATED:",
          updatedOrder
        );





        fetchMyOrders();
      }
    );





    socket.on(

      "orderStatusUpdated",

      (data) => {

        console.log(
          "STATUS UPDATED:",
          data
        );





        fetchMyOrders();
      }
    );





    return () => {

      socket.off("newOrder");

      socket.off("newOrderPlaced");

      socket.off("orderUpdated");

      socket.off("orderStatusUpdated");
    };

  }, []);





  // =========================================
  // AUTO REFRESH
  // =========================================

  useEffect(() => {

    const interval =
      setInterval(() => {

        fetchMyOrders();

      }, 3000);





    return () =>
      clearInterval(interval);

  }, []);





  // =========================================
  // STATUS CLASS
  // =========================================

  const getStatusClass =
    (status) => {

      switch (status) {

        case "Delivered":
        case "delivered":
          return "delivered";

        case "Cancelled":
        case "cancelled":
          return "cancelled";

        case "Preparing":
        case "preparing":
          return "preparing";

        default:
          return "pending";
      }
    };





  // =========================================
  // STATUS ICON
  // =========================================

  const getStatusIcon =
    (status) => {

      switch (status) {

        case "Delivered":
        case "delivered":
          return <FaCheckCircle />;

        case "Cancelled":
        case "cancelled":
          return <FaTimesCircle />;

        default:
          return <FaClock />;
      }
    };





  return (

    <div className="orders-page">

      {/* BACK BUTTON */}

      <button
        onClick={handleBack}
        className="back-btn"
      >

        <FaArrowLeft />

      </button>





      {/* HEADER */}

      <div className="orders-header">

        <h1 className="orders-title">

          <FaShoppingBag />

          My Orders

        </h1>

        <p className="orders-subtitle">

          Track your live canteen orders

        </p>

      </div>





      {/* LOADING */}

      {

        loading ? (

          <div className="loading-box">

            <h2>

              Loading Orders...

            </h2>

          </div>

        ) : (

          <>
            {/* ========================================= */}
            {/* CURRENT ORDERS */}
            {/* ========================================= */}

            <div className="orders-section">

              <h2 className="section-title">

                Current Orders

              </h2>





              {

                currentOrders.length === 0 ? (

                  <div className="empty-box">

                    <FaBoxOpen size={40} />

                    <p>

                      No current orders

                    </p>

                  </div>

                ) : (

                  currentOrders.map((order) => (

                    <div
                      className="modern-order-card"
                      key={order._id}
                    >

                      {/* TOP */}

                      <div className="order-card-top">

                        <div>

                          <h3>

                            Token #

                            {

                              order.tokenNumber ||

                              order.token ||

                              "----"
                            }

                          </h3>





                          <p>

                            {

                              new Date(
                                order.createdAt
                              ).toLocaleString()
                            }

                          </p>

                        </div>





                        <div

                          className={`status-pill ${

                            getStatusClass(

                              order.orderStatus ||

                              order.status
                            )
                          }`}
                        >

                          {

                            getStatusIcon(

                              order.orderStatus ||

                              order.status
                            )
                          }

                          <span>

                            {

                              order.orderStatus ||

                              order.status ||

                              "Pending"
                            }

                          </span>

                        </div>

                      </div>





                      {/* ITEMS */}

                      <div className="order-items">

                        {

                          order.items?.length > 0 ? (

                            order.items.map(

                              (item, index) => (

                                <div
                                  className="order-item-row"
                                  key={index}
                                >

                                  <div>

                                    <h4>

                                      {

                                        item.name ||

                                        item.food?.name ||

                                        "Food Item"
                                      }

                                    </h4>





                                    <p>

                                      Qty :

                                      {

                                        item.quantity || 1
                                      }

                                    </p>





                                    <small>

                                      ₹

                                      {

                                        item.price ||

                                        item.food?.price ||

                                        0
                                      }

                                      {" "}each

                                    </small>

                                  </div>





                                  <span>

                                    ₹

                                    {

                                      (

                                        item.price ||

                                        item.food?.price ||

                                        0

                                      ) *

                                      (

                                        item.quantity || 1
                                      )
                                    }

                                  </span>

                                </div>
                              )
                            )

                          ) : (

                            <div className="empty-items">

                              No items found

                            </div>
                          )
                        }

                      </div>





                      {/* TOTAL */}

                      <div className="order-total">

                        <h3>

                          Total Amount

                        </h3>

                        <span>

                          ₹

                          {

                            order.totalAmount
                          }

                        </span>

                      </div>





                      {/* LIVE STATUS */}

                      <div className="live-status-wrapper">

                        {/* PLACED */}

                        <div className="status-step">

                          <div
                            className={`status-circle ${
                              order.orderStatus === "placed" ||
                              order.orderStatus === "preparing" ||
                              order.orderStatus === "delivered"

                                ? "active-circle"

                                : ""
                            }`}
                          >

                            <FaClipboardList />

                          </div>

                          <p
                            className={`status-text ${
                              order.orderStatus === "placed" ||
                              order.orderStatus === "preparing" ||
                              order.orderStatus === "delivered"

                                ? "active-text"

                                : ""
                            }`}
                          >

                            Placed

                          </p>

                        </div>





                        <div
                          className={`status-bar ${
                            order.orderStatus === "preparing" ||
                            order.orderStatus === "delivered"

                              ? "active-bar"

                              : ""
                          }`}
                        ></div>





                        {/* PREPARING */}

                        <div className="status-step">

                          <div
                            className={`status-circle ${
                              order.orderStatus === "preparing" ||
                              order.orderStatus === "delivered"

                                ? "active-circle"

                                : ""
                            }`}
                          >

                            <FaUtensils />

                          </div>

                          <p
                            className={`status-text ${
                              order.orderStatus === "preparing" ||
                              order.orderStatus === "delivered"

                                ? "active-text"

                                : ""
                            }`}
                          >

                            Preparing

                          </p>

                        </div>





                        <div
                          className={`status-bar ${
                            order.orderStatus === "delivered"

                              ? "active-bar"

                              : ""
                          }`}
                        ></div>





                        {/* DELIVERED */}

                        <div className="status-step">

                          <div
                            className={`status-circle ${
                              order.orderStatus === "delivered"

                                ? "active-circle"

                                : ""
                            }`}
                          >

                            <FaCheckCircle />

                          </div>

                          <p
                            className={`status-text ${
                              order.orderStatus === "delivered"

                                ? "active-text"

                                : ""
                            }`}
                          >

                            Delivered

                          </p>

                        </div>

                      </div>

                    </div>
                  ))
                )
              }

            </div>





            {/* ========================================= */}
            {/* ORDER HISTORY */}
            {/* ========================================= */}

            <div className="orders-section">

              <h2 className="section-title">

                Order History

              </h2>





              {

                historyOrders.length === 0 ? (

                  <div className="empty-box">

                    <FaBoxOpen size={40} />

                    <p>

                      No order history

                    </p>

                  </div>

                ) : (

                  historyOrders.map((order) => (

                    <div
                      className="history-card"
                      key={order._id}
                    >

                      <div className="history-top">

                        <div>

                         <h3 className="token-number">

  Token #

  {

    order.tokenNumber ||

    order.token ||

    order.orderToken ||

    "N/A"

  }

</h3>





                          <p>

                            {

                              new Date(
                                order.createdAt
                              ).toLocaleString()
                            }

                          </p>

                        </div>





                        <div

                          className={`status-pill ${

                            getStatusClass(

                              order.orderStatus ||

                              order.status
                            )
                          }`}
                        >

                          {

                            order.orderStatus ||

                            order.status ||

                            "Pending"
                          }

                        </div>

                      </div>





                      {

                        order.items?.map(

                          (item, index) => (

                            <div
                              className="history-item"
                              key={index}
                            >

                              <span>

                                {

                                  item.name ||

                                  item.food?.name ||

                                  "Food Item"
                                }

                              </span>





                              <span>

                                x

                                {

                                  item.quantity || 1
                                }

                              </span>

                            </div>
                          )
                        )
                      }





                      <div className="history-total">

                        ₹

                        {

                          order.totalAmount
                        }

                      </div>

                    </div>
                  ))
                )
              }

            </div>
          </>
        )
      }

    </div>
  );
}

export default Orders;

