import { useState } from "react";

import {
  useLocation,
  useNavigate
} from "react-router-dom";

import axios from "axios";

import {
  FaArrowLeft,
  FaMoneyBillWave,
  FaQrcode
} from "react-icons/fa";

import qrImage from "../assets/upi-qr.png";

import "../css/Payment.css";

function Payment() {

  // =====================================
  // ROUTER
  // =====================================

  const location =
    useLocation();

  const navigate =
    useNavigate();





  // =====================================
  // DATA
  // =====================================

  const total =
    location.state?.total || 0;

  const cartItems =
    location.state?.cart || [];





  // =====================================
  // STATES
  // =====================================

  const [selectedPlace,
    setSelectedPlace] =

    useState("Cafeteria");



  const [selectedPayment,
    setSelectedPayment] =

    useState("Cash");



  const [loading,
    // eslint-disable-next-line no-unused-vars
    setLoading] =

    useState(false);





  // =====================================
  // BACK BUTTON
  // =====================================

  const handleBack = () => {

    navigate(-1);
  };





  // =====================================
  // PLACE ORDER
  // =====================================

const handleOrder =
  async () => {

    try {

      // GET TOKEN
      const token =
        localStorage.getItem(
          "token"
        );





      // CHECK TOKEN
      if (!token) {

        alert(
          "Please login first"
        );

        navigate("/login");

        return;
      }





      console.log(
        "TOKEN:",
        token
      );





      // FORMAT ITEMS
      const formattedItems =

        cartItems.map(

          (item) => ({

            food:
              item._id,

            name:
              item.name,

            price:
              item.price,

            quantity:
              item.quantity
          })
        );





      console.log(
        "ADDING:",
        formattedItems
      );

const savedToken =
  localStorage.getItem(
    "token"
  );



if (!savedToken) {

  alert(
    "Login again"
  );

  navigate("/");

  return;
}



      // API CALL
      const response =
        await axios.post(

          "https://cvru-cms.onrender.com/api/v1/orders/create",

          {

            items:
              formattedItems,

            totalAmount:
              total,

            paymentMethod:

              selectedPayment ===
              "UPI"

                ? "Online"

                : "Cash",

            specialInstructions:
              "Less spicy",

            orderType:
              "Takeaway",

            deliveryPlace:
              selectedPlace
          },

          {

            headers: {

  authorization:
    `Bearer ${localStorage.getItem("token") || ""}`
}
          }
        );





      console.log(
        "ORDER SUCCESS:",
        response.data
      );





      const order =
        response.data.order;





      navigate(

        "/token",

        {

          state: {

            token:
              order.tokenNumber,

            total,

            place:
              selectedPlace,

            payment:
              selectedPayment,

            cartItems
          }
        }
      );

    } catch (error) {

  console.log(
    "ORDER ERROR:",
    error.response?.data ||
    error
  );





  // TOKEN EXPIRED
  if (

    error.response?.data?.message
      ?.includes("token expired")

    ||

    error.response?.status === 401
  ) {

    // CLEAR OLD TOKEN
    localStorage.removeItem(
      "token"
    );





    alert(
      "Session expired. Please login again."
    );





    navigate("/login");

    return;
  }





  alert(

    error.response?.data?.message ||

    "Order Failed"
  );
}
  };





  return (

    <div className="payment-page">

      {/* BACK BUTTON */}

      <button

        className="back-btn"

        onClick={handleBack}
      >

        <FaArrowLeft />

      </button>





      {/* CARD */}

      <div className="payment-card">

        <h2>

          Checkout

        </h2>





        {/* DELIVERY LOCATION */}

        <div className="section">

          <p className="section-title">

            Deliver To

          </p>





          {

            [

              "Cafeteria",

              "A Block",

              "B Block",

              "Admin Block"

            ].map((place) => (

              <div

                key={place}

                className={`option-box ${

                  selectedPlace ===
                  place

                    ? "active"

                    : ""
                }`}

                onClick={() =>

                  setSelectedPlace(
                    place
                  )
                }
              >

                {place}

              </div>
            ))
          }

        </div>





        {/* PAYMENT METHOD */}

        <div className="section">

          <p className="section-title">

            Payment Method

          </p>





          {/* CASH */}

          <div

            className={`option-box ${

              selectedPayment ===
              "Cash"

                ? "active"

                : ""
            }`}

            onClick={() =>

              setSelectedPayment(
                "Cash"
              )
            }
          >

            <FaMoneyBillWave />

            <span>

              Cash

            </span>

          </div>





          {/* UPI */}

          <div

            className={`option-box ${

              selectedPayment ===
              "UPI"

                ? "active"

                : ""
            }`}

            onClick={() =>

              setSelectedPayment(
                "UPI"
              )
            }
          >

            <FaQrcode />

            <span>

              UPI

            </span>

          </div>





          {/* QR IMAGE */}

          {

            selectedPayment ===
            "UPI"

            && (

              <div className="small-qr-box">

                <img

                  src={qrImage}

                  alt="QR"

                  className="small-qr"
                />





                <p>

                  Scan to Pay

                </p>

              </div>
            )
          }

        </div>





        {/* TOTAL */}

        <div className="total-section">

          <p>

            Total Amount

          </p>





          <h2>

            ₹ {total}

          </h2>

        </div>





        {/* ORDER BUTTON */}

        <button

          className="place-order-btn"

          onClick={handleOrder}

          disabled={loading}
        >

          {

            loading

              ? "Placing Order..."

              : "Place Order"
          }

        </button>

      </div>

    </div>
  );
}

export default Payment;

