// UPDATE USER PROFILE
// =========================================

const updateUserProfile =
  async (req, res) => {

    try {

      const {

        name,

        email,

        password

      } = req.body;





      // ======================================
      // VALIDATION
      // ======================================

      if (!name || !email) {

        return res.status(400).json({

          success: false,

          message:
            "Name and Email are required"
        });
      }





      // ======================================
      // FIND USER
      // ======================================

      const user =
        await User.findById(
          req.user.id
        );





      if (!user) {

        return res.status(404).json({

          success: false,

          message:
            "User not found"
        });
      }





      // ======================================
      // CHECK EMAIL EXISTS
      // ======================================

      const existingUser =
        await User.findOne({

          email
        });





      if (

        existingUser &&

        existingUser._id.toString()

        !==

        req.user.id
      ) {

        return res.status(400).json({

          success: false,

          message:
            "Email already exists"
        });
      }





      // ======================================
      // UPDATE DATA
      // ======================================

      user.name = name;

      user.email = email;





      // PASSWORD UPDATE
      if (

        password &&

        password.trim() !== ""
      ) {

        const hashedPassword =
          await bcrypt.hash(

            password,

            10
          );





        user.password =
          hashedPassword;
      }





      await user.save();





      // ======================================
      // RESPONSE
      // ======================================

      res.status(200).json({

        success: true,

        message:
          "Profile updated successfully",

        user: {

          _id: user._id,

          name: user.name,

          email: user.email
        }
      });

    } catch (error) {

      console.log(error);





      res.status(500).json({

        success: false,

        message:
          "Failed to update profile"
      });
    }
  };

