const googleLogin =
async (req, res) => {

  try {

    const { credential } =
      req.body;





    // VERIFY TOKEN
    const ticket =
      await client.verifyIdToken({

        idToken: credential,

        audience:
          process.env.GOOGLE_CLIENT_ID
      });





    const payload =
      ticket.getPayload();





    const {

      email,

      name,

      picture

    } = payload;





    // FIND USER
    let user =
      await User.findOne({

        email
      });





    // CREATE USER
    if (!user) {

      user = await User.create({

        userName: name,

        email,

        profilePic: picture,

        password:
          "google-login-user"
      });
    }





    // JWT TOKEN
    const token =
      jwt.sign(

        {
          id: user._id
        },

        process.env.JWT_SECRET,

        {
          expiresIn: "7d"
        }
      );





    // COOKIE
    res.cookie(

      "token",

      token,

      {

        httpOnly: true,

        secure: false,

        sameSite: "lax"
      }
    );





    res.status(200).json({

      success: true,

      user
    });

  } catch (error) {

    console.log(
      "GOOGLE LOGIN ERROR:",
      error
    );





    res.status(500).json({

      success: false,

      message:
        "Google Login Failed"
    });
  }
};
